package net.civeira.phylax.feature.observe.observeddashboard.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.ObservedDashboardBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class ObservedDashboardBatchController implements ObservedDashboardBatchApi {

  /**
   * ObservedDashboard
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ObservedDashboardDeleteController deleteController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param code
   * @param sourceKind
   * @param name
   * @return
   */
  @Override
  public Response observedDashboardApiBatchDelete(final List<String> uids, final String search,
      final String code, final String sourceKind, final String name) {
    return deleteController.observedDashboardApiBatchDelete(uids, search, code, sourceKind, name);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response observedDashboardApiBatchDeleteQuery(final String batchId) {
    return deleteController.observedDashboardApiBatchDeleteQuery(batchId);
  }
}
